window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"nrMuMkobNeo","speaker":"Maxim Ryzhenkov","role":"Foreign Minister","country":"Belarus","region":"Europe","url":"https://www.youtube.com/watch?v=nrMuMkobNeo","date":"20260926","title":"🇧🇾 Belarus - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":924,"words":2535,"counts":{"claims":30,"promises":2,"attacks":15},"topics":[{"topic":"UN Security Council reform","share":0.1388,"seconds":128},{"topic":"Ukraine conflict","share":0.1384,"seconds":128},{"topic":"International crisis","share":0.1356,"seconds":125},{"topic":"EU sanctions","share":0.1338,"seconds":124},{"topic":"UN reform","share":0.1317,"seconds":122},{"topic":"Western policy","share":0.1166,"seconds":108},{"topic":"Strategic arms","share":0.0703,"seconds":65},{"topic":"Belarus economy","share":0.0686,"seconds":63},{"topic":"WWII reparations","share":0.0662,"seconds":61}],"timeline":[[5,68,null],[69,132,"International crisis"],[133,198,"Strategic arms"],[200,263,"Western policy"],[264,327,"EU sanctions"],[328,389,"UN Security Council reform"],[390,451,"WWII reparations"],[452,517,"Ukraine conflict"],[518,578,"EU sanctions"],[579,639,"UN reform"],[640,707,"UN Security Council reform"],[708,770,"International crisis"],[771,832,"UN reform"],[833,897,"Belarus economy"],[898,960,"Ukraine conflict"],[961,1007,"Western policy"]],"stances":{"International crisis":"Maxim Ryzhenkov states that member states have failed to enable the organization to act due to endless debates, resulting in a systemic crisis characterized by wars, conflicts, and the collapse of strategic stability.","Strategic arms":"Maxim Ryzhenkov states that the absence of legally binding limits on strategic arms is an inevitable result of actions by certain states aimed at undermining international relations.","Western policy":"Maxim Ryzhenkov argues that Western countries have abandoned international law to enforce self-designed rules that suppress other nations while exempting themselves.","EU sanctions":"Maxim Ryzhenkov argues that the European Union is intensifying unfair trade practices and illegal unilateral sanctions to preserve its slipping hegemony, thereby undermining global stability and sacrificing the well-being of its own citizens.","UN Security Council reform":"Maxim Ryzhenkov states that Belarus supported the UN General Assembly resolution declaring the trafficking of enslaved Africans as a crime against humanity without hesitation.","WWII reparations":"Maxim Ryzhenkov asserts that Belarus suffered genocide and plunder during WWII by Europeans, supports the African Union's demand for historical justice and reparations, and argues that reparations extend beyond financial compensation.","Ukraine conflict":"Maxim Ryzhenkov asserts that the West's goal in Ukraine is to inflict a civilizational defeat on Russia rather than achieve peace.","UN reform":"Maxim Ryzhenkov argues that the UN is failing to adapt to new realities and requires reform driven by countries prioritizing global welfare over selfish interests.","Belarus economy":"Maxim Ryzhenkov states that Belarus is successfully contributing to global food security and remains a reliable supplier despite Western restrictions."},"claims":[{"t":105,"quote":"Wars and conflicts are engulfing the world. They are claiming lives, tearing families apart. turning thriving cities into ruins and giving rise to ever more waves of mass forced migration.","topic":"International crisis","kind":"fact"},{"t":118,"quote":"Global supply chains are being disrupted. The energy crisis is entwined with the food crisis.","topic":"International crisis","kind":"fact"},{"t":129,"quote":"An even more alarming sign is the collapse of the system of strategic stability.","topic":"International crisis","kind":"fact"},{"t":133,"quote":"For the first time since the 1970s, there are no longer any legally binding limits on strategic arms between the major nuclear powers.","topic":"Strategic arms","kind":"fact"},{"t":143,"quote":"There are no treaties, no verification mechanisms, and no Humanity is once again teetering on the brink of existence.","topic":"Strategic arms","kind":"fact"},{"t":257,"quote":"Yugoslavia, Iraq, Libya, Syria, Venezuela, Cuba, Iran, Palestine.","topic":"Western policy","kind":"fact"},{"t":278,"quote":"illegal unilateral sanctions that are suffocating entire nations","topic":"EU sanctions","kind":"fact"},{"t":286,"quote":"The organization has not been able to resolve a single serious conflict","topic":"EU sanctions","kind":"fact"},{"t":367,"quote":"the UN General Assembly adopted a resolution in March of this year declaring the trafficking of enslaved Africans and racialized cattle enslavement of Africans as the gravest crime against humanity.","topic":"UN Security Council reform","kind":"fact"},{"t":378,"quote":"Belarus supported this resolution without hesitation.","topic":"UN Security Council reform","kind":"self_credit"},{"t":392,"quote":"A third of our population during the war was murdered in cold blood and tortured by civilized Europeans uh united by Hitler 85 years ago.","topic":"WWII reparations","kind":"number"},{"t":422,"quote":"Our wealth, resources, works of art were all taken to the west. Young people were forcibly taken into slavery there as well in Europe.","topic":"WWII reparations","kind":"fact"},{"t":465,"quote":"the great waterfall that the peoples of Zimbabwe have for centuries called Mossio, the smoke that thunders, the colonizers quote unquote discovered it 150 years ago and named it after their queen who had never even set foot in Africa.","topic":"Ukraine conflict","kind":"fact"},{"t":506,"quote":"Its goal, as they say, is to inflict a civilizational defeat on Russia, to weaken, humiliate, and break it, and to continue living off Russian resources, but not at the cost of its own citizens lives.","topic":"Ukraine conflict","kind":"fact"},{"t":523,"quote":"It allows them to create an image of the enemy, mobilize their own population under the pretext of a collective threat, blame economic failures that we see on this conflict, justify militarization, and of course to enrich themselves.","topic":"EU sanctions","kind":"fact"},{"t":565,"quote":"putting aside the self-imposed isolation to which the EU is condemning itself by creating a new iron curtain along its borders with Barus and Russia.","topic":"EU sanctions","kind":"fact"},{"t":587,"quote":"Criticism of our organization is growing every year and um it is fairly justified the very fact that new international global initiatives are emerging outside the system for example Trump's board of peace or the world artificial intelligence cooperation organization uh China's project this confirms that the UN is failing to recognize new trends that is why new formats of cooperation are emerging the bricks the SEO and regional economic and political alliances and they are gaining momentum","topic":"UN reform","kind":"fact"},{"t":653,"quote":"This body cannot remain in a form that was appropriate for the midentth century.","topic":"UN Security Council reform","kind":"fact"},{"t":682,"quote":"The UN charter has been and remains the only universal document that recognizes the sovereign equality of all states.","topic":"UN Security Council reform","kind":"fact"},{"t":717,"quote":"The use of these organizations for political purposes must be nipped in the bud. This also applies to the International Labor Organization.","topic":"International crisis","kind":"fact"},{"t":728,"quote":"today the ILO in the finest traditions of the Communist International is attempting to cultivate revolutionary forces in some countries out of labor unions and not to protect workers rights, but to destabilize the situation in countries that are pursuing independent policies at the behest of certain other countries.","topic":"International crisis","kind":"fact"},{"t":762,"quote":"It is therefore no surprise that many equate the work of our organization with its secretariat, which is dominated by representatives of Western countries.","topic":"International crisis","kind":"fact"},{"t":805,"quote":"The Republic of Belarus is a founding member of the United Nations. We were there at the very beginning of the organization in 1945","topic":"UN reform","kind":"fact"},{"t":833,"quote":"We are developing successfully and making a significant contribution to global food security.","topic":"Belarus economy","kind":"fact"},{"t":838,"quote":"Belarus remains a reliable supplier of fertilizers, highquality food, meat, dairy products, and grain to countries in Africa, Asia, and Latin America.","topic":"Belarus economy","kind":"fact"},{"t":882,"quote":"The failure to implement the Minsk agreements which were the only legitimate path to peace.","topic":"Belarus economy","kind":"fact"},{"t":915,"quote":"In since 2023, we have successfully been holding an international conference on this in our capital where experts from across Eurasia discuss ways to solve our continent's problems.","topic":"Ukraine conflict","kind":"fact"},{"t":925,"quote":"We are successfully promoting the idea of drafting a Eurasian charter on diversity and multipolarity in the 21st century.","topic":"Ukraine conflict","kind":"self_credit"},{"t":962,"quote":"the uniolar world, as we can see, is sinking. Western elites are accustomed to dominance and they are trying to keep it afloat.","topic":"Western policy","kind":"fact"},{"t":969,"quote":"But in their futile efforts, they are only sewing chaos.","topic":"Western policy","kind":"fact"}],"promises":[{"t":826,"quote":"In these circumstances, Belarus is making its contribution to creating a new world. First of all, on food security.","topic":"UN reform","kind":"promise"},{"t":866,"quote":"we're ready to continue doing everything possible to achieve peace in Ukraine as soon as possible.","topic":"Belarus economy","kind":"promise"}],"attacks":[{"t":159,"quote":"It is the inevitable result of actions by certain states aimed at deliberately undermining the system of international relations so that the world would develop not according to the laws of peaceful coexistence but rather the principle of might makes right and political selfishness.","topic":"Strategic arms","target":"Unnamed opponents"},{"t":233,"quote":"Western countries have effectively trampled on international law and started to force everyone to act according to so-called rules, destroying unwelcome countries and suppressing unbounded peoples.","topic":"Western policy","target":"Western countries"},{"t":302,"quote":"The leadership of the European Union is particularly worrying. They have an unbralled desire to preserve their slipping hedgemony and they're attempting to undermine global stability and the maintenance of peace.","topic":"EU sanctions","target":"European Union"},{"t":402,"quote":"Now their descendants are telling us that they had have nothing to do with this and nor did their grandfathers supposedly.","topic":"WWII reparations","target":"Western countries"},{"t":484,"quote":"Western elites do not like the new multipolar world in which their voice is no longer decisive. But instead of adapting to positive changes, they continue to so uh to to exploit instability.","topic":"Ukraine conflict","target":"Western countries"},{"t":502,"quote":"Is the West really striving to achieve peace there? No. Its goal, as they say, is to inflict a civilizational defeat on Russia, to weaken, humiliate, and break it, and to continue living off Russian resources, but not at the cost of its own citizens lives.","topic":"Ukraine conflict","target":"Western countries"},{"t":570,"quote":"creating a new iron curtain along its borders with Barus and Russia","topic":"EU sanctions","target":"European Union"},{"t":728,"quote":"today the ILO in the finest traditions of the Communist International is attempting to cultivate revolutionary forces in some countries out of labor unions and not to protect workers rights, but to destabilize the situation in countries that are pursuing independent policies at the behest of certain other countries.","topic":"International crisis","target":"International Labor Organization"},{"t":762,"quote":"It is therefore no surprise that many equate the work of our organization with its secretariat, which is dominated by representatives of Western countries.","topic":"International crisis","target":"Western countries"},{"t":772,"quote":"this is a world of comfortable offices, of sky-high salaries, and a lifestyle that is very far removed from the concerns of those in need of assistance in various corners of our planet. Many of those officials have never even been to the conflict zones","topic":"UN reform","target":"United Nations"},{"t":796,"quote":"it is a criticism of us the member states who have allowed this to become the norm who have allowed this to happen","topic":"UN reform","target":"European Union"},{"t":849,"quote":"despite the lo logistical barriers, financial restrictions and transport blockades imposed by the European Union.","topic":"Belarus economy","target":"European Union"},{"t":886,"quote":"And let me remind you that the implementation of these agreements was sabotaged in order to buy time and allow Ukraine to rearm and that has been acknowledged by by Western politicians very recently.","topic":"Belarus economy","target":"Western countries"},{"t":957,"quote":"Pressure, dictates, ultimatums and illegal sanctions.","topic":"Ukraine conflict","target":"Western countries"},{"t":966,"quote":"Western elites are accustomed to dominance and they are trying to keep it afloat. But in their futile efforts, they are only sewing chaos.","topic":"Western policy","target":"Western countries"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":5,"topic":null,"text":"I now give the floor to his excellency Maxine Rzanov, Minister of Foreign Affairs of Bellarus. See that? &gt;&gt; Mr. President, ladies and gentlemen, let us begin with the theme of today's debate. Restoring trust, managing a united nations that delivers for all. It is an interesting theme that allows us for a very substantive discussion which we have been witnessing for a week now. Indeed, trust among states today is at its lowest point since the cold war. The necessary reforms are stalling. More and more voices are saying that the UN is not working in the interests of all and is incapable of managing change."},{"t":69,"topic":"International crisis","text":"This is largely because we the member states have in large part become mired in endless debates but have failed to give the organization a real opportunity to act. That is precisely why the theme of this session sounds today like a verdict on our collective indecision and at the same time as a diagnosis calling for urgent treatment. We are surrounded by a systemic crisis in international relations. We see this everywhere. The air is thick with anxiety from Europe to the Middle East, from Asia to Africa and Latin America. Wars and conflicts are engulfing the world. They are claiming lives, tearing families apart. turning thriving cities into ruins and giving rise to ever more waves of mass forced migration. Global supply chains are being disrupted. The energy crisis is entwined with the food crisis. And all of this hits the most vulnerable segments of the population the hardest. An even more alarming sign is the collapse of the system of strategic stability."},{"t":133,"topic":"Strategic arms","text":"For the first time since the 1970s, there are no longer any legally binding limits on strategic arms between the major nuclear powers. There are no treaties, no verification mechanisms, and no Humanity is once again teetering on the brink of existence. That is a brink that we had hoped we had left for good in the last century. How did we reach this point? Well, it is no mere coincidence. It is the inevitable result of actions by certain states aimed at deliberately undermining the system of international relations so that the world would develop not according to the laws of peaceful coexistence but rather the principle of might makes right and political selfishness. If we truly want to restore trust, we must not hide behind diplomatic nicities, but honestly identify the causes of crisis. In 1945 in San Francisco at the UN founding conference, US President Harry Truman spoke words that today sound like a No matter how great our strength, we must deny ourselves the license to do always as we please."},{"t":200,"topic":"Western policy","text":"If all those with great power had acted as Truman said, we would have avoided many wars and conflicts. Unfortunately, however, the desire to live at the expense of others has remained the dominant narrative in the collective west's development. During the Cold War, the balance of power was maintained by a system of checks and balances between the two opposing political systems. But since the 1990s, when that balance collapsed, the policy of unrestrained superiority has begun to grow rapidly. And in recent years, this policy has reached its peak. Western countries have effectively trampled on international law and started to force everyone to act according to so-called rules, destroying unwelcome countries and suppressing unbounded peoples. And these rules are like traffic signs in a city that they themselves have designed. They always have a green light while everyone else faces strict restrictions. But this isn't about metaphors. It is about facts that everyone knows. Yugoslavia, Iraq, Libya, Syria, Venezuela, Cuba, Iran, Palestine."},{"t":264,"topic":"EU sanctions","text":"And this is by no means an exhaustive list of the countries that have been or remain the focus of greedy Western interest. Now, let's add to that unfair global trade where the rules are written to serve the interests of transnational corporations and also illegal unilateral sanctions that are suffocating entire nations. And those efforts are intensifying. But what is the UN doing? The organization has not been able to resolve a single serious conflict. Its role has instead boiled down to managing concerns, making appeals to those who have already suffered and that of is of course leading to further escalation. The leadership of the European Union is particularly worrying. They have an unbralled desire to preserve their slipping hedgemony and they're attempting to undermine global stability and the maintenance of peace. And to achieve this, they are prepared to sacrifice even the well-being of their own citizens. Do the peoples of the United Europe really crave some sort of revenge against Russia, especially at the cost of their own impoverishment?"},{"t":328,"topic":"UN Security Council reform","text":"Of course they don't. Do they want to be cannon foder in a war that allegedly European politicians are preparing for by 2030? Of course not. And we know this. But in Brussels, someone is very eager to play toy soldiers and to cement their greatness in history. This has happened before, more than once, and we know how it ended. Nevertheless, in the West, they are already beginning to ask questions about they're now being held to account for centuries of colonial plunder, for the destruction of cultures, traditions, and identifiers of enslaved peoples, and for the slave trade which claimed millions of lives. And in line with this, the UN General Assembly adopted a resolution in March of this year declaring the trafficking of enslaved Africans and racialized cattle enslavement of Africans as the gravest crime against humanity. Belarus supported this resolution without hesitation. This is not just a diplomatic gesture. It is the voice of a country that has itself endured a similar hellish chapter in history."},{"t":390,"topic":"WWII reparations","text":"We know what genocide is. A third of our population during the war was murdered in cold blood and tortured by civilized Europeans uh united by Hitler 85 years ago. Now their descendants are telling us that they had have nothing to do with this and nor did their grandfathers supposedly. But that village house filled with Bellarusian children, the elderly and women was not burned down by the furer himself. And there were thousands of such houses. We know what the plundering of cultural heritage means. Our wealth, resources, works of art were all taken to the west. Young people were forcibly taken into slavery there as well in Europe. And today, facing unprecedented sanctions, we have once again felt what it means to be a target. That is why we wholeheartedly and with fraternal feeling support those who demand historical justice, including on the issue of reparations raised by the African Union. But reparations are not just about money."},{"t":452,"topic":"Ukraine conflict","text":"They are also about respectful memory. They are about returning people's own history to them. How many names remain on the world map that have erased millennia old memory? Here's a simple example. the great waterfall that the peoples of Zimbabwe have for centuries called Mossio, the smoke that thunders, the colonizers quote unquote discovered it 150 years ago and named it after their queen who had never even set foot in Africa. What is that if not identity theft? Western elites do not like the new multipolar world in which their voice is no longer decisive. But instead of adapting to positive changes, they continue to so uh to to exploit instability. In Bellarus, we see this most clearly in the example of Ukraine. Is the West really striving to achieve peace there? No. Its goal, as they say, is to inflict a civilizational defeat on Russia, to weaken, humiliate, and break it, and to continue living off Russian resources, but not at the cost of its own citizens lives."},{"t":518,"topic":"EU sanctions","text":"rather at the cost of ordinary Ukrainians. Such a war is profitable for them. It allows them to create an image of the enemy, mobilize their own population under the pretext of a collective threat, blame economic failures that we see on this conflict, justify militarization, and of course to enrich themselves. That is why they need the conflict, a controlled, frozen, and eternal conflict. But if the West wants to take its rightful place in the emerging multipolar world, it must change. It must understand that the future of our planet lies in cooperation and not confrontation. Yes, it will have to make room on the global bench of international relations and do so in a meaningful way. It will require abandoning the policies of neocolonialism and putting aside the self-imposed isolation to which the EU is condemning itself by creating a new iron curtain along its borders with Barus and Russia. Uh now on the UN, is our organization keeping pace with the times?"},{"t":579,"topic":"UN reform","text":"No, it does not correspond to today's realities. It cannot keep up with change and it is not reforming significantly. Criticism of our organization is growing every year and um it is fairly justified the very fact that new international global initiatives are emerging outside the system for example Trump's board of peace or the world artificial intelligence cooperation organization uh China's project this confirms that the UN is failing to recognize new trends that is why new formats of cooperation are emerging the bricks the SEO and regional economic and political alliances and they are gaining momentum But we in Belarus do not see them as competitors to the UN, but rather as catalysts for a necessary reform. We have a recipe for restoring the UN to its intended purpose. And it's very simple. Individual countries must stop using the organization, our shared organization, for their own selfish ends. And they must begin to think about the fate of our planet, our shared planet as a whole."},{"t":640,"topic":"UN Security Council reform","text":"Only then will the theme of this session cease to be a romantic wish and instead become a real program of action. Concrete structural steps are also necessary. First reform of the UN security council. This body cannot remain in a form that was appropriate for the midentth century. The council must be strengthened by expanding the category of permanent members to include the countries of the south which today play an everinccreasing role in world affairs. The voice of the global majority must be heard loud and clear in the security council. Second, restoring respect for international law and the UN charter and specifically respect for the law, not the rules-based order. The UN charter has been and remains the only universal document that recognizes the sovereign equality of all states. Third, reform of specialized UN agencies. First and foremost, the international financial institutions, the World Bank, the International Monetary Fund, the International Finance Corporation, the World Trade Organization, they must become fair, transparent, accountable, and focused on their mandates."},{"t":708,"topic":"International crisis","text":"Voting quotas in financial institutions must reflect the demographic and economic realities of the 21st century rather than the post-war balance of power. The use of these organizations for political purposes must be nipped in the bud. This also applies to the International Labor Organization. One might think its mission is to promote social dialogue. However, today the ILO in the finest traditions of the Communist International is attempting to cultivate revolutionary forces in some countries out of labor unions and not to protect workers rights, but to destabilize the situation in countries that are pursuing independent policies at the behest of certain other countries. And most importantly, with each new crisis, ordinary people around the world are asking themselves, why isn't the UN working to establish peace? People aren't interested in the UN's constraints. They want to see action and results, and there are none. It is therefore no surprise that many equate the work of our organization with its secretariat, which is dominated by representatives of Western countries."},{"t":771,"topic":"UN reform","text":"And just like in Brussels, this is a world of comfortable offices, of sky-high salaries, and a lifestyle that is very far removed from the concerns of those in need of assistance in various corners of our planet. Many of those officials have never even been to the conflict zones and they are much further away from them than any volunteer on the front lines. And this is of course not so much a criticism of the secretariat rather it is a criticism of us the member states who have allowed this to become the norm who have allowed this to happen. The Republic of Belarus is a founding member of the United Nations. We were there at the very beginning of the organization in 1945 and so it pains us to see the weakening of the UN. Therefore we offer constructive criticism of the organization hoping that it can recover and take on a new lease on life. We are convinced that the UN must remain the primary universal forum for addressing common challenges. In these circumstances, Belarus is making its contribution to creating a new world. First of all, on food security."},{"t":833,"topic":"Belarus economy","text":"We are developing successfully and making a significant contribution to global food security. Belarus remains a reliable supplier of fertilizers, highquality food, meat, dairy products, and grain to countries in Africa, Asia, and Latin America. and we are doing this despite the lo logistical barriers, financial restrictions and transport blockades imposed by the European Union. Uh second, our role in peace. Belarus has always been and remains a country of peace. We've proven our ability to serve as a reliable platform for negotiations and we're ready to continue doing everything possible to achieve peace in Ukraine as soon as possible. But let's be frank, any lasting peace in that country is not possible without addressing the root causes which have been ignored for years. These include plans to bring Ukraine into NATO contrary to all security realities. The failure to implement the Minsk agreements which were the only legitimate path to peace. And let me remind you that the implementation of these agreements was sabotaged in order to buy time and allow Ukraine to rearm and that has been acknowledged by by Western politicians very recently."},{"t":898,"topic":"Ukraine conflict","text":"The endless supply of weapons to Ukraine will only lead to the destruction of Ukraine itself and its people. We call for the prompt beginning of genuine negotiations that will lead to a lasting peace. Third, the Eurasian security architecture. Uh this is our particular priority, ensuring Eurasian security. In since 2023, we have successfully been holding an international conference on this in our capital where experts from across Eurasia discuss ways to solve our continent's problems. We are successfully promoting the idea of drafting a Eurasian charter on diversity and multipolarity in the 21st century. This initiative is part of an effort to create a new architecture of equal and indivisible security on our vast continent stretching from the Atlantic to the Pacific. Finally, our openness to dialogue. We are ready to cooperate with all interested countries. We also are leaving the door open to those western pol politicians who are genuinely ready for a dialogue of equals. But there are things that are unacceptable for us. Pressure, dictates, ultimatums and illegal sanctions."},{"t":961,"topic":"Western policy","text":"Mr. President, the uniolar world, as we can see, is sinking. Western elites are accustomed to dominance and they are trying to keep it afloat. But in their futile efforts, they are only sewing chaos. We've spoken about this alarming trend last year as well, calling for action. But we see that nothing is changing and it's only getting worse. Therefore, Belarus and the countries of the global majority do not wish to to go down with the wreckage of this ship and we are choosing a different path. We are building a multipolar and just world of equal states in the interests of all of our peoples. We have no other choice. Thank you for your attention. I thank the Minister of Foreign Affairs of Bellarus."}],"compare":[{"topic":"UN & its reform","share":0.2705,"mean":0.2044,"rank":56,"others":170},{"topic":"Russia-Ukraine War","share":0.1384,"mean":0.0348,"rank":17,"others":44},{"topic":"Regional Security","share":0.1356,"mean":0.0039,"rank":1,"others":12},{"topic":"Sanctions","share":0.1338,"mean":0.0024,"rank":2,"others":5},{"topic":"Europe","share":0.1166,"mean":0.0036,"rank":2,"others":8},{"topic":"Nuclear Disarmament","share":0.0703,"mean":0.0037,"rank":6,"others":9},{"topic":"Reparations","share":0.0662,"mean":0.0041,"rank":4,"others":13}]};
